var t=`0730-boule`;var n=`world-0730`;var s=`TD`;var r=`central-africa`;var o=8;var a=49;var l={en:`Boule`,ua:`Буле`};var u={en:`Boule is a Chad classic prepared with millet flour. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Буле, страва кухні країни Чад зі складниками: пшоняне борошно. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var g=[{en:`Cook the listed ingredients in simmering water for about 10 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 10 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:10,i:[[`water`,1050,`ml`],[`table-salt`,4,`g`]]},{en:`Slowly stir the grains into the simmering liquid; cook over low heat for about 27 minutes, stirring to prevent sticking.`,ua:`Повільно всипте крупу в гарячу рідину; варіть на слабкому вогні приблизно 27 хвилин, помішуючи, щоб не пристала до дна.`,t:[`absorption-cooking`],m:27,i:[[`millet-flour`,370,`g`]]},{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:9,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`unsalted-butter`,35,`g`]]}];var d={slug:t,id:n,country:`TD`,region:r,servings:8,minutes:49,title:l,text:u,steps:g};export{s as country,d as default,n as id,a as minutes,r as region,o as servings,t as slug,g as steps,u as text,l as title};